function save(){
 if(storageLoadIssue){rollbackSave();toast('Saved data needs recovery. Open Data & Beta to download the original file before changing anything.','error');return false;}
 if(!deviceProfile){rollbackSave();toast('Enter your device space before saving.','error');return false;}
 try{RVLivingCore.sync(data,committedData);const serialized=JSON.stringify(data);localStorage.setItem(STORAGE_KEY,serialized);committedData=JSON.parse(serialized);RVConnect.changed();showSaveState(false);try{localStorage.removeItem(LEGACY_KEY)}catch{}return true;}
 catch(e){rollbackSave();toast('Could not save. Browser storage may be full or disabled. Export a backup if possible.','error');return false;}
}
// Restore/import is committed to storage BEFORE changing the in-memory workspace.
// If storage fails, the previous workspace is left intact and the UI reports failure.
function commitReplacement(next){
 if(!deviceProfile)throw Error('Open a local profile before restoring data.');
 localStorage.setItem(STORAGE_KEY,JSON.stringify(next));
 try{localStorage.removeItem(LEGACY_KEY)}catch{}
 data=next;committedData=clone(next);RVConnect.changed();showSaveState(false);storageLoadIssue=null;hb12Undo=null;
}
function downloadRawRecovery(){
 const raw=localStorage.getItem(STORAGE_KEY)||localStorage.getItem(LEGACY_KEY);
 if(!raw){toast('There is no saved file to download.','error');return;}
 const link=document.createElement('a'),u=URL.createObjectURL(new Blob([raw],{type:'application/json'}));
 link.href=u;link.download=`rowanvale-raw-recovery-${todayKey()}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);
 toast('Raw saved file downloaded. Keep it safe before attempting repairs.','success');
}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg,type=''){const region=$('#toastRegion');if(!region)return;region.replaceChildren();const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;region.append(el);setTimeout(()=>el.remove(),3600)}
function todayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dayLabel(){return new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date()).toUpperCase()}
// Progressive levels: 100 XP for level 2, with each next step 10 XP larger.
function thresholdForLevel(level){const n=Math.max(0,level-1);return 100*n+5*n*(n-1)}
function levelFor(xp){let lvl=1;while(lvl<1000&&thresholdForLevel(lvl+1)<=Math.max(0,xp))lvl++;return lvl}
function levelProgress(xp){const level=levelFor(xp),start=thresholdForLevel(level),next=thresholdForLevel(level+1);return Math.round(100*Math.max(0,Math.min(1,(xp-start)/(next-start))))}
function nextLevelXP(xp){return Math.max(0,thresholdForLevel(levelFor(xp)+1)-Math.max(0,xp))}
