function startOfWeek(d=new Date()){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}
function cycleKey(q,now=new Date()){if(q.repeat==='daily')return todayKey();if(q.repeat==='weekly'){const d=startOfWeek(now);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}return q.id}
function rolloverQuests(){let changed=false;for(const q of data.quests){if(!['daily','weekly'].includes(q.repeat))continue;const key=cycleKey(q);if(q.completed&&q.cycleKey&&q.cycleKey!==key){q.completed=false;q.completedDate=null;changed=true}if(q.cycleKey!==key){q.cycleKey=key;changed=true}}if(changed&&deviceProfile)if(!save())return false;return changed}
function awardXP(amount,reason,key,lane='Personal'){return RVLivingCore.award(data,amount,reason,key,lane);}
function weeklyLedger(){const from=startOfWeek().getTime();return (data.xpEvents||[]).filter(e=>e.active!==false&&Number.isFinite(Date.parse(e.date))&&Date.parse(e.date)>=from)}
function weeklyScoreboard(){const scores=LANES.map(lane=>({lane,points:weeklyLedger().filter(e=>e.lane===lane).reduce((v,e)=>v+e.amount,0)}));return scores.sort((a,b)=>b.points-a.points||a.lane.localeCompare(b.lane))}
function personalBestWeek(){const totals={};for(const e of data.xpEvents||[]){if(!Number.isFinite(Date.parse(e.date)))continue;const key=cycleKey({repeat:'weekly'},new Date(e.date));totals[key]=(totals[key]||0)+e.amount}return Math.max(0,...Object.values(totals))}
function weeklyChallenges(){const from=startOfWeek().getTime();const quests=data.quests.filter(q=>q.completed&&q.completedDate&&Date.parse(q.completedDate+'T12:00:00')>=from).length;const focus=data.focusLog.filter(f=>Date.parse(f.date)>=from).reduce((n,f)=>n+(Number(f.minutes)||0),0);const sessions=data.playLog.filter(f=>Date.parse(f.date)>=from).length;return [{title:'Complete 3 quests',have:quests,goal:3,view:'quests'},{title:'Focus for 60 minutes',have:focus,goal:60,view:'focus'},{title:'Log 2 game sessions',have:sessions,goal:2,view:'backlog'}]}
function playerRank(){const score=weeklyLedger().reduce((n,e)=>n+e.amount,0);return score>=500?'Legend':score>=250?'Diamond':score>=125?'Gold':score>=60?'Silver':'Bronze'}
function completedToday(){return data.quests.filter(q=>q.completed && q.completedDate===todayKey()).length}
function minutes(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}
