function hb12ResolvedAppearance(){
 const mode=data.settings.appearanceMode||'theme';
 if(mode==='system')return window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';
 if(mode==='theme')return hb12ThemeDefaultDark(data.settings.theme)?'dark':'light';
 return mode;
}
