  document.body.dataset.motion=data.settings.reducedMotion?'reduced':(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches?'system-reduced':'full');
  document.body.dataset.atmosphere=data.settings.atmosphere||'night-garden';
  document.body.dataset.cardStyle=data.settings.cardStyle||'glass';
  document.body.dataset.typeScale=data.settings.typeScale||'normal';
  document.body.dataset.spaceWallpaper=data.settings.spaceWallpaper||'nebula';
  document.body.dataset.spaceLayout=data.settings.spaceLayout||'bento';
