  document.body.dataset.interfaceWidth=data.settings.interfaceWidth||'standard';
  document.body.dataset.overlayStyle=data.settings.overlayStyle||'glass';
  document.body.dataset.theme=data.settings.theme||'afterglow';
  document.body.dataset.appearanceResolved=hb12ResolvedAppearance();document.documentElement.dataset.initialAppearance=document.body.dataset.appearanceResolved;document.documentElement.style.colorScheme=document.body.dataset.appearanceResolved;
  document.body.dataset.appearanceMode=data.settings.appearanceMode||'theme';
  const basePack=HB12_THEME_PACKS[data.settings.theme];
