  document.body.style.setProperty('--accent',modeAccent);
  document.body.style.setProperty('--accent-rgb',hexRgb(modeAccent));
  document.body.style.setProperty('--hb12-onaccent',hb12ColorInk(modeAccent));
  document.body.dataset.uiDensity=data.settings.uiDensity||'balanced';
  document.body.dataset.uiCorners=data.settings.uiCorners||'soft';
  document.body.dataset.uiBackdrop=data.settings.uiBackdrop||'ambient';
  document.body.dataset.uiFont=data.settings.uiFont||'system';
