  document.body.dataset.sensory=data.settings.lowStimulation?'low':'normal';
  document.body.dataset.clutter=data.settings.lowClutter?'low':'standard';
  document.body.dataset.progressDisplay=data.settings.progressDisplay||'gentle';
  document.body.dataset.feedbackStyle=data.settings.feedbackStyle||'gentle';
  document.body.dataset.quietClock=data.settings.quietClockHidden?'hidden':'visible';
  const fonts={system:'ui-sans-serif,system-ui,-apple-system,"Segoe UI",Arial,sans-serif',rounded:'"Trebuchet MS",ui-rounded,system-ui,sans-serif',serif:'Georgia,"Times New Roman",serif',mono:'ui-monospace,"Cascadia Code",Consolas,monospace'};
  document.body.style.setProperty('--hb12-font',fonts[data.settings.uiFont]||fonts.system);
  document.body.style.setProperty('--hb12-onaccent',hb12ColorInk(modeAccent));
  document.body.classList.toggle('focus-mode',data.settings.focusMode!==false);
  const custom=data.settings.rv18?.version?'':data.settings.customWallpaper||'';
  if(/^data:image\/(png|jpeg|webp|gif);base64,/i.test(custom)&&custom.length<1300000) document.body.style.setProperty('--custom-wallpaper-url',`url(\"${custom}\")`);
  else document.body.style.removeProperty('--custom-wallpaper-url');
  $('#topAvatar').textContent=(data.profile.avatarEmoji||'✦').trim()||'✦';
  const shell=$('#appShell');if(shell)shell.classList.toggle('sidebar-collapsed',!!data.settings.sidebarCollapsed);
  const collapse=$('#sidebarToggle');if(collapse){const collapsed=!!data.settings.sidebarCollapsed;collapse.setAttribute('aria-expanded',String(!collapsed));collapse.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');collapse.dataset.hint=collapsed?'Bring back section names and the full navigation.':'Make more room for your current page. Navigation stays available as icons.';collapse.title=collapsed?'Expand navigation':'Collapse navigation';collapse.querySelector('svg')?.classList.toggle('is-collapsed',collapsed)}
  const sideName=$('#sidebarProfileName');if(sideName)sideName.textContent=(data.profile.name||'Your space').trim().slice(0,26);
