function hexRgb(hex){return [1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)).join(',')}
const VIEW_LABELS={media:'Games & Media',books:'Books Directory',fan:'Fan Lounge',watch:'Watch Room',clubhouse:'Clubhouse',myday:'My Day',resources:'Offline Guides',safety:'Backups & Data',dashboard:'Overview',space:'Your Orbit',quests:'Quests',focus:'Quiet Room',discover:'Discover Games',backlog:'Game Collection',wellness:'Reset Studio',fitness:'Movement',customize:'Settings',updates:'Help & Updates',friends:'Friends',connections:'Connections'};
let activeHintTarget=null;
function hideUiHint(){
 const tip=document.getElementById('uiHintBubble');
 if(tip){tip.classList.remove('is-visible');tip.setAttribute('aria-hidden','true')}
 if(activeHintTarget){activeHintTarget.removeAttribute('aria-describedby');activeHintTarget=null}
}
function showUiHint(el){
 const message=String(el?.dataset?.hint||'').trim();if(!message)return;
 let tip=document.getElementById('uiHintBubble');
 if(!tip){tip=document.createElement('div');tip.id='uiHintBubble';tip.className='ui-hint-bubble';tip.setAttribute('role','tooltip');tip.setAttribute('aria-hidden','true');document.body.appendChild(tip)}
 if(activeHintTarget&&activeHintTarget!==el)activeHintTarget.removeAttribute('aria-describedby');
 activeHintTarget=el;el.setAttribute('aria-describedby','uiHintBubble');tip.textContent=message;
 tip.classList.remove('is-visible');tip.setAttribute('aria-hidden','false');
 tip.style.left='12px';tip.style.top='12px';
 const r=el.getBoundingClientRect(), t=tip.getBoundingClientRect(), gap=10, pad=12;
 const sidebarItem=el.matches('.nav-item')&&el.closest('.sidebar')&&getComputedStyle(el.closest('.sidebar')).display!=='none';
 let left,top;
 if(sidebarItem){
  left=r.right+gap;
  if(left+t.width>innerWidth-pad)left=r.left-t.width-gap;
  top=r.top+(r.height-t.height)/2;
 }else if(el.closest('.mobile-nav')||el.closest('.top-actions')||el.id==='commandLaunch'||el.classList.contains('guide-launcher')){
  left=r.right-t.width;
  top=r.top-t.height-gap;
  if(top<pad)top=r.bottom+gap;
 }else{
  left=r.left+(r.width-t.width)/2;
  top=r.top-t.height-gap;
  if(top<pad)top=r.bottom+gap;
 }
 left=Math.max(pad,Math.min(left,innerWidth-t.width-pad));
 top=Math.max(pad,Math.min(top,innerHeight-t.height-pad));
 tip.style.left=`${Math.round(left)}px`;tip.style.top=`${Math.round(top)}px`;
 requestAnimationFrame(()=>tip.classList.add('is-visible'));
}
document.addEventListener('pointerover',e=>{const el=e.target.closest?.('[data-hint]');if(el&&el!==activeHintTarget)showUiHint(el)});
document.addEventListener('pointerout',e=>{const el=e.target.closest?.('[data-hint]');if(el&&el===activeHintTarget&&!el.contains(e.relatedTarget)&&!el.contains(document.activeElement))hideUiHint()});
document.addEventListener('focusin',e=>{const el=e.target.closest?.('[data-hint]');if(el)showUiHint(el)});
document.addEventListener('focusout',e=>{const el=e.target.closest?.('[data-hint]');if(el&&el===activeHintTarget&&!el.contains(e.relatedTarget)&&!el.matches(':hover'))hideUiHint()});
document.addEventListener('scroll',hideUiHint,true);
window.addEventListener('resize',hideUiHint);

