function applyHelpfulHints(root=document,skipGameGrid=false){
 if(!root||!root.querySelectorAll)return;
 root.querySelectorAll('[data-view]').forEach(el=>{const hint=VIEW_HINTS[el.dataset.view];if(hint){el.setAttribute('data-hint',hint);if(!el.hasAttribute('title'))el.setAttribute('title',hint)}});
 root.querySelectorAll('[data-action]').forEach(el=>{
  if(skipGameGrid&&el.closest('#gameGrid'))return;
  const action=el.dataset.action||'';
  const label=(el.getAttribute('aria-label')||el.textContent||'').replace(/\s+/g,' ').trim().slice(0,90);
  let hint=ACTION_HINTS[action]||el.getAttribute('title')||'';
  if(!hint&&/^(delete|remove)/.test(action))hint='Remove this item from your local workspace.';
  else if(!hint&&/^edit/.test(action))hint='Open the editor for this item.';
  else if(!hint&&/^(save|add|create|new)/.test(action))hint='Save this choice to your local workspace.';
  else if(!hint&&/^export/.test(action))hint='Download a file you can keep or share.';
  else if(!hint&&/^import/.test(action))hint='Choose a compatible file to bring data into the app.';
  else if(!hint&&/^open/.test(action))hint='Open the related tool, section, or dialog.';
  else if(!hint&&/^toggle/.test(action))hint='Turn this option on or off.';
  else if(!hint&&label)hint=`${label}: use this control to manage this part of your workspace.`;
  if(hint){el.setAttribute('data-hint',hint);if(!el.hasAttribute('title'))el.setAttribute('title',hint)}
 });
 Object.entries(CONTROL_HINTS).forEach(([id,hint])=>{const el=document.getElementById(id);if(el){el.setAttribute('data-hint',hint);if(!el.hasAttribute('title'))el.setAttribute('title',hint)}});
 root.querySelectorAll('[data-hint][title]').forEach(el=>el.removeAttribute('title'));
}

