function libraryVisibleItems(){
 const q=libraryQuery.trim().toLocaleLowerCase();
 const matches=data.backlog.filter(x=>{
   if(backlogFilter!=='All' && (backlogFilter.startsWith('Shelf:')?x.shelf!==backlogFilter.slice(6):x.status!==backlogFilter))return false;
   return !q || [x.title,x.note,x.status,x.shelf,x.type].some(field=>String(field||'').toLocaleLowerCase().includes(q));
 });
 const dateTime=x=>{const n=Date.parse(x||'');return Number.isFinite(n)?n:0};
 matches.sort((a,b)=>{
  if(librarySort==='title')return String(a.title).localeCompare(String(b.title));
  if(librarySort==='status')return String(a.status).localeCompare(String(b.status))||String(a.title).localeCompare(String(b.title));
  if(librarySort==='played')return dateTime(b.lastPlayedAt)-dateTime(a.lastPlayedAt)||String(a.title).localeCompare(String(b.title));
  if(librarySort==='oldest')return dateTime(a.createdAt)-dateTime(b.createdAt);
  return dateTime(b.createdAt)-dateTime(a.createdAt);
 });
 return matches;
}
function libraryCardMarkup(x){
 const isGame=(x.type||'Game')==='Game';
 const statuses=isGame?['Wishlist','Backlog','Currently Playing','Completed','On Hold','Dropped']:['Want to Try','In Progress','Finished'];
 const icon=({'Game':'◈','Movie':'▣','Anime':'✧','Show':'▤','Book':'▥'})[x.type]||'◈';
 const label=x.status||'Backlog';
 const last=x.lastPlayedAt && !isNaN(Date.parse(x.lastPlayedAt))?new Date(x.lastPlayedAt).toLocaleDateString():'';
 const artSrc=isGame?RV17.coverFor(x.title,x.background_image,data,x.id):'';
 return `<article class="backlog-item hb10-library-card" data-library-title="${esc(x.title)}" data-library-status="${esc(label)}"><label class="rv162-card-select" title="Select game for batch editing"><input type="checkbox" class="rv162-select-game" value="${esc(x.id)}" aria-label="Select ${esc(x.title)}"> Select</label>
 <div ${RVCovers.mark(x)} class="backlog-icon hb10-library-art ${artSrc?'rv17-has-cover':''}" aria-hidden="true">${artSrc?`<img src="${esc(artSrc)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" alt="">`:`<span>${icon}</span><small>${esc(x.type||'Game')}</small>`}</div>
 <div class="backlog-info hb10-library-info"><span class="hb10-library-kicker">${esc(x.type||'Game')} <span aria-hidden="true">/</span> ${esc(label)}</span><b class="hb10-library-title">${esc(x.title)}</b>
 <small class="hb10-library-subtitle">${x.note?esc(x.note):'No personal note yet.'}${last?' · Last played '+esc(last):''}</small>
 <div class="hb10-card-shortcuts">${isGame?RV17.coverButton(x.title,'Cover',x.id):''}${isGame?`<button type="button" class="hb10-text-action" data-action="log-play-from-library" data-id="${esc(x.id)}">▶ Log play</button>`:''}<button type="button" class="hb10-text-action" data-action="library-edit-note" data-id="${esc(x.id)}">✎ Edit note</button>${isGame&&label!=='Completed'?`<button type="button" class="hb10-text-action" data-action="library-quick-status" data-id="${esc(x.id)}" data-value="Completed">✓ Complete</button>`:''}</div></div>
 <div class="hb10-card-controls"><label>Status <select data-action="backlog-status" data-id="${esc(x.id)}" aria-label="Status for ${esc(x.title)}">${statuses.map(st=>`<option ${label===st?'selected':''}>${esc(st)}</option>`).join('')}</select></label>
 <label>Shelf <select class="library-item-shelf" data-action="backlog-shelf" data-id="${esc(x.id)}" aria-label="Custom shelf for ${esc(x.title)}"><option value="" ${!x.shelf?'selected':''}>No custom shelf</option>${(data.customShelves||[]).map(sh=>`<option value="${esc(sh)}" ${x.shelf===sh?'selected':''}>${esc(sh)}</option>`).join('')}</select></label>
 <button type="button" class="tiny-button hb10-delete" data-action="backlog-delete" data-id="${esc(x.id)}" aria-label="Remove ${esc(x.title)} from Collection">×</button></div></article>`;
}
function updateLibraryResults(){
 const root=$('#libraryResults');if(!root)return;
 // Batch toolbar selection persists through search/sort without changing any card actions.
 const matches=libraryVisibleItems();root.innerHTML=matches.length?matches.slice(0,libraryLimit).map(libraryCardMarkup).join(''):empty('No games in this view.','Try a different search or shelf, or add your first title.','<button class="button button-primary" data-action="new-backlog">＋ Add an item</button>');
 const meta=$('#libraryResultCount');if(meta)meta.textContent=`${matches.length.toLocaleString()} of ${data.backlog.length.toLocaleString()} items${matches.length>LIBRARY_PAGE_SIZE?' · '+Math.min(libraryLimit,matches.length)+' displayed':''}`;
 const more=$('#libraryLoadMore');if(more){more.hidden=matches.length<=libraryLimit;more.textContent=`Load more titles · ${Math.min(LIBRARY_PAGE_SIZE,Math.max(0,matches.length-libraryLimit))} next`;}
 const clear=$('#librarySearchClear');if(clear)clear.hidden=!libraryQuery;
 applyHelpfulHints(root);
 RV162.decorateLibrary(root,data);
}
