async function searchFitnessResource(kind,form){
 const query=form.querySelector('input[type=search]').value.trim();if(query.length<2)return;
 const status=kind==='recipes'?'recipeStatus':'exerciseStatus';const el=$('#'+status);const submit=form.querySelector('button[type=submit]');
 submit.disabled=true;if(el)el.textContent='Searching online…';
 try{const r=await fetch(`/api/${kind}?search=${encodeURIComponent(query)}`,{headers:{Accept:'application/json'},signal:AbortSignal.timeout(11000)});const out=await r.json();if(!r.ok)throw Error(out.error||'Search unavailable');
 resourceResults[kind]=Array.isArray(out.results)?out.results:[];resourceStatus[kind]=resourceResults[kind].length?`${resourceResults[kind].length} results · ${out.source}${out.developmentKey?' · Development API access':''}`:'No matches. Try a different phrase.';
 }catch(e){resourceResults[kind]=[];resourceStatus[kind]=e.name==='TimeoutError'?'Search timed out. Try again.':(e.message||'Resource unavailable.');}
 if(currentView==='fitness'){
  const prior=kind==='recipes'?'recipeQuery':'exerciseQuery';const savedQuery=query;
  render();const input=$('#'+prior);if(input)input.value=savedQuery;
 }
}
function openFoodDialog(prefill=null,editId=''){
 $('#foodLogForm').dataset.editId=editId;$('#foodLogDialog h2').textContent=editId?'Edit food entry':'Log food';
 $('#foodLogForm')?.reset();$('#foodDate').value=diaryDay();$('#foodName').value=prefill?.name||'';$('#foodServingLabel').value=prefill?.servingLabel||'serving';
 $('#foodServings').value=prefill?.servings||1;if(prefill?.meal)$('#foodMeal').value=prefill.meal;if(prefill?.day)$('#foodDate').value=prefill.day;
 for(const x of ['calories','protein','carbs','fat']){const field=$('#food'+x[0].toUpperCase()+x.slice(1));field.required=false;field.step='any';field.placeholder='Unknown';field.value=prefill?.[x]??'';}
 $('#foodLogDialog .small-note').textContent='Enter nutrition per serving; totals multiply by servings. Leave unknown values blank. Zero means a confirmed zero.';
 $('#foodLogDialog')?.showModal();$('#foodName')?.focus();
}
function saveFoodLog(){
 const name=$('#foodName').value.trim(),servings=Number($('#foodServings').value),values={};
 if(!name||!Number.isFinite(servings)||servings<=0||servings>100){toast('Check food name and serving count.','error');return}
 for(const k of ['calories','protein','carbs','fat']){const raw=$('#food'+k[0].toUpperCase()+k.slice(1)).value;const n=Number(raw);if(raw!==''&&(!Number.isFinite(n)||n<0||n>10000)){toast('Check the nutrition numbers.','error');return}values[k]=raw===''?null:fixed(n*servings)}
 const day=$('#foodDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||ymd(new Date(day+'T12:00:00'))!==day){toast('Choose a valid diary date.','error');return}
 const prior=clone(data);
 const editId=$('#foodLogForm').dataset.editId,entry={id:editId||uid(),name:name.slice(0,100),meal:$('#foodMeal').value,servingLabel:$('#foodServingLabel').value.trim().slice(0,60)||'serving',servings,day,...values};
 if(editId){const index=data.foodLogs.findIndex(x=>x.id===editId);if(index<0){toast('This food entry no longer exists.','error');return}data.foodLogs[index]={...data.foodLogs[index],...entry};}else data.foodLogs.unshift(entry);
 if(!save()){data=prior;return;}$('#foodLogDialog').close();render();toast('Food entry saved on this device.','success');
}
function openPlanDialog(preset='',editId=''){
 const plan=editId?(data.workoutPlans||[]).find(x=>x.id===editId):null;
 $('#workoutPlanForm').reset();$('#planId').value=plan?.id||'';
 $('#planName').value=plan?.name||'';$('#planMoves').value=plan?.moves||preset;$('#planNote').value=plan?.note||'';
 $('#planDialogTitle').textContent=plan?'Edit workout routine':'Build a workout routine';
 $('#planSaveButton').textContent=plan?'Save changes':'Save routine';
 $('#workoutPlanDialog').showModal();$('#planName').focus();
}
function savePlan(){
 const name=$('#planName').value.trim(),moves=$('#planMoves').value.trim(),editId=$('#planId').value;
 if(!name||!moves){toast('Name your routine and add its movements.','error');return}
 const prior=clone(data),entry={name:name.slice(0,100),moves:moves.slice(0,1000),note:$('#planNote').value.trim().slice(0,300)};
 if(editId){const index=data.workoutPlans.findIndex(x=>x.id===editId);if(index<0){toast('This routine no longer exists.','error');return}data.workoutPlans[index]={...data.workoutPlans[index],...entry}}
 else {data.workoutPlans.unshift({id:uid(),...entry});}
 if(!save()){data=prior;return}$('#workoutPlanDialog').close();render();toast(editId?'Routine changes saved.':'Workout routine saved locally.','success');
}
async function lookupBarcode(){const code=$('#barcodeCode').value.trim(),status=$('#barcodeStatus');if(!/^\d{8,14}$/.test(code)){status.textContent='Enter 8–14 digits.';return}
 const submit=$('#barcodeForm button[type=submit]');submit.disabled=true;status.textContent='Checking product…';
 try{const r=await fetch(`/api/barcode?code=${encodeURIComponent(code)}`,{signal:AbortSignal.timeout(11000)});const item=await r.json();if(!r.ok)throw Error(item.error||'Barcode lookup unavailable');if(!item.found){status.textContent='Barcode not found. You can log it manually.';return}
 const n=item.product.per100g;$('#barcodeDialog').close();openFoodDialog({name:item.product.name,servingLabel:'100 g (check label)',calories:n.calories,protein:n.protein,carbs:n.carbs,fat:n.fat});toast('Imported per-100 g values. Verify packaging and portion before saving.');
 }catch(e){status.textContent=e.message||'Could not look up the product.'}finally{submit.disabled=false}
}

function openFitnessLog(templateId='',editId=''){
 const templates={strength:{title:'Strength foundations',activity:'Strength',minutes:20,note:'Squat or sit-to-stand · push · hinge · carry. Adapt to comfort.'},walk:{title:'Walk, roll, or easy cardio',activity:'Walking',minutes:15,note:'Comfortable pace; indoors or outdoors.'},mobility:{title:'Mobility reset',activity:'Mobility',minutes:8,note:'Gentle, comfortable range only.'},yoga:{title:'Yoga & balance pause',activity:'Yoga',minutes:12,note:'Supported and comfortable movement.'},dance:{title:'One-song dance break',activity:'Dance',minutes:4,note:'Move however feels good; breaks are welcome.'},sport:{title:'Practice or play',activity:'Sport',minutes:25,note:'Easy start, skill/play time, then cool down.'}};
 const t=templates[templateId],entry=editId?(data.fitnessLogs||[]).find(x=>x.id===editId):null;
 const form=$('#fitnessLogForm');form?.reset();
 $('#fitnessId').value=entry?.id||'';
 $('#fitnessDialogTitle').textContent=entry?'Edit movement session':'Log a movement session';
 $('#fitnessSaveButton').textContent=entry?'Save changes':'Save session';
 $('#fitnessDate').max=todayKey();$('#fitnessDate').value=entry?fitnessLocalDate(entry.date):todayKey();
 if(entry){$('#fitnessTitle').value=entry.title||'';$('#fitnessActivity').value=entry.activity||'Other';$('#fitnessMinutes').value=entry.minutes||15;$('#fitnessEffort').value=entry.effort||'Steady';$('#fitnessNote').value=entry.note||''}
 else if(t){$('#fitnessTitle').value=t.title;$('#fitnessActivity').value=t.activity;$('#fitnessMinutes').value=t.minutes;$('#fitnessNote').value=t.note}
 else {$('#fitnessTitle').value='';$('#fitnessActivity').value='Walking';$('#fitnessMinutes').value='15';$('#fitnessNote').value=''}
 $('#fitnessLogDialog').showModal();$('#fitnessTitle')?.focus();
}
function saveFitnessSessionFromForm(){
 const title=$('#fitnessTitle')?.value.trim()||'',activity=$('#fitnessActivity')?.value||'Other',mins=Number($('#fitnessMinutes')?.value||0),effort=$('#fitnessEffort')?.value||'Steady',note=$('#fitnessNote')?.value.trim()||'';
 const selectedDate=$('#fitnessDate')?.value||'',editId=$('#fitnessId')?.value||'';
 const validDate=/^\d{4}-\d{2}-\d{2}$/.test(selectedDate)&&ymd(new Date(selectedDate+'T12:00:00'))===selectedDate&&selectedDate<=todayKey();
 if(!title||!Number.isFinite(mins)||mins<1||mins>600||!Number.isInteger(mins)){toast('Add a session name and a whole-minute duration between 1 and 600.','error');return}
 if(!validDate){toast('Choose a valid session date that is not in the future.','error');return}
 if(!['Walking','Cardio','Strength','Mobility','Yoga','Dance','Sport','Recovery','Other'].includes(activity)){toast('Choose a movement type.','error');return}
 const prior=clone(data),date=new Date(selectedDate+'T12:00:00').toISOString();
 if(editId){const index=data.fitnessLogs.findIndex(x=>x.id===editId);if(index<0){toast('This session no longer exists.','error');return}
   data.fitnessLogs[index]={...data.fitnessLogs[index],title:title.slice(0,100),activity,minutes:mins,effort,note:note.slice(0,300),date};
 }else{
   const entry={id:uid(),title:title.slice(0,100),activity,minutes:mins,effort,note:note.slice(0,300),date};
   data.fitnessLogs.unshift(entry);
   if(mins>=5)awardXP(Math.min(30,10+Math.floor(mins/15)*5),`Movement: ${title}`,`fitness:${entry.id}`,'Fitness');checkAchievements();
 }
 if(!save()){data=prior;return}
 $('#fitnessLogDialog').close();go('fitness');toast(editId?'Movement session updated.':'Movement session saved locally.','success');
}

function renderCommandResults(query=''){
 const sections=[['myday','My Day','Your personalized launchpad','☀','today daily widgets'],['dashboard','Home Base','Overview and shortcuts','◈','home'],['space','Your Orbit','Profile and favorites','✦','profile'],['discover','Discover','Find games in the archive','⌘','games catalog'],['backlog','Game Collection','Saved games and shelves','▤','games library'],['media','Your Library','Games, books, movies, TV and anime together','▤','media collection'],['books','Books Directory','Find your next book','▥','reading books editions'],['watch','Watch Room','Movies, TV shows and anime','▷','watch movies television anime'],['fan','Fan Lounge','Compare titles and plan a night together','✦','night voting plans'],['fitness','Fitness & Movement','Activity, recipes, and workouts','✺','nutrition meals water'],['wellness','Reset Studio','Mood and grounding','✧','mental wellness'],['quests','Quest Circuit','Challenges and XP','✳','tasks'],['focus','Quiet Room','Gentle timer and brain dump','◷','focus'],['customize','Profile Studio','Themes and personalization','⚙','settings'],['clubhouse','Clubhouse','Game nights, shareable quests, and saved plans','♜','offline plan night kit'],['friends','Friends','Private roster','♧','crew'],['connections','Connections','Platform shortcuts','⛓','spotify'],['resources','Offline Guides','Recipes and workout starters','▦','food moves'],['safety','Data & Beta','Backups, undo and recovery','♙','backup restore'],['updates','Update Center','Versions and reliability','↻','release']];
 for(const section of sections){const label=document.querySelector('#appSidebar .nav-item[data-view="'+section[0]+'"] .nav-label')?.textContent?.trim();if(label){section[4]+=' '+section[1];section[1]=label;}}
 const q=String(query||'').toLocaleLowerCase().trim(),hits=[];
 sections.filter(x=>!q||x.slice(1).join(' ').toLocaleLowerCase().includes(q)).forEach(([view,title,desc,icon])=>hits.push({kind:'section',title,desc,icon,view}));
 if(q.length>=2){
  const add=(items,kind,view,titleOf,descOf,icon,max=8)=>{let n=0;for(const x of items||[]){if(n>=max)break;const title=String(titleOf(x)||'');const desc=String(descOf(x)||'');if((title+' '+desc).toLocaleLowerCase().includes(q)){hits.push({kind,view,title:title.slice(0,140),desc:desc.slice(0,120),icon,itemId:x.id,itemType:x.type});n++}}};
  add(data.backlog,'media-item','media',x=>x.title,x=>(x.type||'Game')+' · '+(x.status||'')+' · '+(x.author||x.bookMeta?.author||'')+' '+(x.note||''),'▤',20);
  add(data.quests,'quest','quests',x=>x.title,x=>x.note||x.category,'✳',10);
  add(data.friends,'friend','friends',x=>x.name,x=>(x.handle||'')+' '+(x.game||''),'♧',8);
  add(data.workoutPlans,'routine','fitness',x=>x.name,x=>x.moves||'','✺',6);
  add(data.savedRecipes,'recipe','fitness',x=>x.title,x=>(x.ingredients||[]).join(' '),'▦',6);
  add(HB12_RECIPES,'resource','resources',x=>x.name,x=>x.ingredients||'','▦',4);
  add(GAMES,'archive','discover',x=>x.name,x=>x.desc||'','⌘',6);
 }
 hb12SearchMatches=hits.slice(0,40);
 const results=$('#commandResults');if(!results)return;
 results.innerHTML=hb12SearchMatches.length?hb12SearchMatches.map((x,i)=>`<button class="command-result" role="option" type="button" data-action="hb12-search-pick" data-value="${i}"><span class="command-result-icon">${x.icon}</span><span><b>${esc(x.title)}</b><small>${esc(x.kind==='section'?x.desc:(x.kind==='media-item'?(x.itemType||'Game').toUpperCase():x.kind.toUpperCase())+' · '+x.desc)}</small></span><kbd>↵</kbd></button>`).join(''):'<div class="command-empty">No matches in this device. Try a title, a person, or a section name.</div>';
}
