function connectionStatusText(platform, record){
 if(platform==='spotify'){
  let token=null;try{token=JSON.parse(sessionStorage.getItem('vytron.spotify.tokens')||'null')}catch{}
  if(token?.accessToken&&token.expiresAt>Date.now())return 'Spotify connected in this tab';
  return record?.profileUrl?'Playlist/profile link saved':record?.displayName?'Authorized before; reconnect in this tab':'Not connected';
 }
 return (record?.profileUrl||record?.handle)?'Profile details saved locally':'Not linked yet';
}
