async function testCatalogEndpoint(){
 const raw=$('#catalogEndpoint')?.value.trim()||data.settings.catalogEndpoint||'/api/games';
 if(!raw){toast('Enter a catalog proxy URL first.');return}
 try{const u=new URL(raw,location.origin);if(u.protocol!=='https:'&&u.hostname!=='localhost')throw new Error('Published endpoints must use HTTPS.');u.searchParams.set('search','minecraft');const r=await fetch(u.toString(),{headers:{Accept:'application/json'}});if(!r.ok)throw new Error(`HTTP ${r.status}`);const j=await r.json();if(!Array.isArray(j)&&!Array.isArray(j.results))throw new Error('Response needs a results array.');toast('Catalog proxy responded with a valid results array.','success')}
 catch(e){toast(`Catalog test failed: ${e.message}`,'error')}
}
