function hb12DayKey(date){return new Date(date).toLocaleDateString('en-CA')}
function hb12EntryDate(item){return item?.date||item?.completedDate||item?.day||item?.createdAt||''}
function hb12ActivityFor(day){
 const relevant=(arr)=>Array.isArray(arr)?arr.filter(item=>{const raw=hb12EntryDate(item);if(!raw)return false;return /^\d{4}-\d{2}-\d{2}$/.test(raw)?raw===day:!Number.isNaN(Date.parse(raw))&&hb12DayKey(raw)===day}):[];
 const sets=[['Play',relevant(data.playLog)],['Movement',relevant(data.fitnessLogs)],['Focus',relevant(data.focusLog)],['Meals',relevant(data.foodLogs)],['Water',relevant(data.waterLogs)],['Wellness',relevant(data.wellnessSessions)],['Quests',relevant(data.quests.filter(q=>q.completed))]];
 const entries=sets.flatMap(([kind,rows])=>rows.map(item=>({kind,text:String(item.title||item.name||item.kind||(kind==='Water'?`${item.ml||0} ml`:(kind==='Meals'?'Food logged':'Completed'))).slice(0,100),raw:hb12EntryDate(item)})));
 return {entries,counts:sets.filter(([,rows])=>rows.length).map(([name,rows])=>`${name}: ${rows.length}`)};
}
function hb12DateStrip(){const today=new Date();const days=Array.from({length:14},(_,i)=>{const d=new Date(today);d.setDate(today.getDate()-(13-i));return d});const chosen=hb12SelectedDay||hb12DayKey(today),details=hb12ActivityFor(chosen);return `<div class="hb12-calendar" aria-label="Last 14 days activity">${days.map(d=>{const key=hb12DayKey(d),n=hb12ActivityFor(key).entries.length;return `<button type="button" class="hb12-day ${key===chosen?'selected':''}" data-action="hb12-day" data-value="${key}" aria-pressed="${key===chosen}" aria-label="${esc(d.toDateString())}, ${n} entries"><small>${d.toLocaleDateString(undefined,{weekday:'short'})}</small><b>${d.getDate()}</b><i class="${n?'active':''}" aria-hidden="true"></i></button>`}).join('')}</div><div class="hb12-day-detail"><strong>${esc(new Date(chosen+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}))}</strong><span>${details.counts.length?esc(details.counts.join(' · ')):'Nothing logged, and that is okay.'}</span></div>${details.entries.length?`<div class="hb12-timeline">${details.entries.slice(0,14).map(x=>`<div><span class="tag">${esc(x.kind)}</span><span>${esc(x.text)}</span></div>`).join('')}</div>`:''}`}
function hb12GamePick(){let items=data.backlog.filter(x=>(x.type||'Game')==='Game'&&x.status!=='Dropped'&&x.status!=='Completed');const selected=data.settings.dayMood||'Any';if(selected!=='Any'){const narrowed=items.filter(x=>(x.title+' '+(x.note||'')).toLowerCase().includes(selected.toLowerCase()));if(narrowed.length)items=narrowed}const m=Number(data.settings.dayMinutes)||60;const idx=items.length?Math.abs([...(`${hb12DayKey(new Date())}|${m}|${selected}`)].reduce((acc,ch)=>(acc*31+ch.charCodeAt(0))|0,7))%items.length:0;return items[idx]||null}
