 RV18.bind({data:()=>data,refresh(){data=loadData();committedData=clone(data);},render,commit(next){const prior=clone(data);data.settings=clone(next.settings);data.profile=clone(next.profile);data.savedLooks=clone(next.savedLooks||[]);if(!save()){data=prior;return false;}librarySort=data.settings.librarySort||'recent';libraryView=data.settings.libraryView||'grid';return true;},preview(kind,next){const prior=data;try{data={...data,settings:clone(next.settings),profile:clone(next.profile)};return kind==='profile'?spacePage():hb12MyDay();}finally{data=prior;}},decoratePreview(kind,root,next){RV162.afterRender(kind==='profile'?'space':'myday',root,next);},specialized(){const t=document.createElement('template');t.innerHTML=customizePage();const titles=['Daily-care habits','Account & cloud sync','About, credits & rights','Live game archive'];return RV162.studio(data,esc)+[...t.content.querySelectorAll('section')].filter(el=>titles.includes(el.querySelector('h2,h3')?.textContent.trim())).map(el=>el.outerHTML).join('');},pins(){document.querySelector('#lwEditPins')?.click();}});
