let pendingFocusCompletion=null,focusSessionId=null,quietRecoveryWarned=false;
const quietTimerOwner=uid(),QUIET_DURABLE_KEY='rowanvale.quiet193.session';
function startTimer(){
 if(pendingFocusCompletion){completeTimer();return}
 if(running){running=false;remaining=Math.max(0,Math.ceil((endAt-Date.now())/1000));clearInterval(focusTimer);focusTimer=null;saveTimerState();updateTimerUI();return}
 if(remaining<=0)remaining=duration*60;
 running=true;endAt=Date.now()+remaining*1000;sessionStartedAt=Date.now();focusTimer=setInterval(tick,250);saveTimerState();updateTimerUI();
}
function saveTimerState(){const state=JSON.stringify({remaining,running,endAt,duration,focusKind,pendingFocusCompletion,focusSessionId,owner:quietTimerOwner});try{sessionStorage.setItem('mindforge.timer',state)}catch{}try{localStorage.setItem(QUIET_DURABLE_KEY,state)}catch{if(!quietRecoveryWarned){quietRecoveryWarned=true;toast('Timer recovery could not be saved to this device. Keep this tab open until your session is saved.','error')}}}
function tick(){if(!running)return;try{const shared=JSON.parse(localStorage.getItem(QUIET_DURABLE_KEY)||'null');if(shared?.owner&&shared.owner!==quietTimerOwner){running=false;clearInterval(focusTimer);focusTimer=null;remaining=Math.max(0,Math.ceil((endAt-Date.now())/1000));updateTimerUI();toast('This focus timer was opened in another tab. This tab is paused.');return;}}catch{}remaining=Math.max(0,Math.ceil((endAt-Date.now())/1000));updateTimerUI();if(remaining<=0)completeTimer()}
function completeTimer(){
 clearInterval(focusTimer);focusTimer=null;running=false;remaining=0;
 const entry=pendingFocusCompletion||{id:focusSessionId||uid(),date:new Date().toISOString(),minutes:duration,kind:focusKind};pendingFocusCompletion=entry;saveTimerState();
 const mins=entry.minutes;
 if(!data.focusLog.some(x=>x.id===entry.id)){
  data.focusLog.unshift(entry);if(!entry.early){awardXP(Math.max(5,Math.round(mins/5)*5),`${entry.kind} · ${mins} min`,`focus:${entry.id}`,'Focus');checkAchievements(false);}
  if(!save()){updateTimerUI();return false}
 }
 pendingFocusCompletion=null;saveTimerState();updateTimerUI();
 toast(entry.early?'Elapsed focus time saved. No completion XP was awarded.':`${focusKind} complete · +${Math.max(5,Math.round(mins/5)*5)} XP. Take a breath if that would help.`,'success');
 if(!entry.early&&data.settings.breakReminder) setTimeout(()=>{if(confirm('You completed a focus session. Would a short break feel good?'))toast('Break idea: stand up, sip water, or look away from the screen.');},250);
}
function updateTimerUI(){
 const display=$('#timerDisplay');if(display)display.textContent=minutes(remaining);
 const status=$('#timerStatus');if(status)status.textContent=pendingFocusCompletion?'FINISHED · SAVE NEEDED':running?'IN PROGRESS':remaining===0?'SESSION COMPLETE':'READY WHEN YOU ARE';
 const ring=$('#timerRing');if(ring)ring.style.setProperty('--timer-progress',`${Math.max(0,Math.min(100,(1-remaining/(duration*60))*100))}%`);
 const start=$('#timerStart');if(start)start.textContent=pendingFocusCompletion?'Retry saving session':running?'Ⅱ Pause':'▶ Start focus';
 const mode=$('#timerModeLabel');if(mode)mode.textContent=focusKind.toUpperCase()+' SESSION';
 const mini=$('#miniTimer');if(mini)mini.textContent=minutes(remaining);
}
function toggleBreathing(){
 if(breathingActive){
  breathingActive=false;clearInterval(breathingTimer);clearInterval(breathingPhaseTimer);breathingTimer=null;breathingPhaseTimer=null;
  const passed=Math.max(0,120-Math.ceil((breathingDeadline-Date.now())/1000));
  if(passed>=20){data.wellnessSessions=data.wellnessSessions||[];data.wellnessSessions.unshift({id:uid(),title:`Breathing pause · ${Math.min(120,passed)} sec`,date:new Date().toISOString(),kind:'breathing'});save()}
  render();toast('Breathing exercise stopped. It is okay to pause early.');return;
 }
 breathingActive=true;breathingDeadline=Date.now()+120000;breathingPhaseIndex=0;
 breathingPhaseTimer=setInterval(()=>{if(!breathingActive)return;breathingPhaseIndex=(breathingPhaseIndex+1)%BREATH_PHASES.length;const label=$('#breathPhaseLabel');if(label)label.textContent=BREATH_PHASES[breathingPhaseIndex].label;const orb=$('#breathOrb');if(orb){orb.dataset.phase=String(breathingPhaseIndex);orb.classList.toggle('breath-in',breathingPhaseIndex===0);orb.classList.toggle('breath-hold',breathingPhaseIndex===1);orb.classList.toggle('breath-out',breathingPhaseIndex===2);orb.classList.toggle('breath-rest',breathingPhaseIndex===3)}},BREATH_PHASES[0].duration*1000);
 breathingTimer=setInterval(()=>{const rem=Math.max(0,Math.ceil((breathingDeadline-Date.now())/1000));const label=$('#breathTimeLabel');if(label)label.textContent=`${rem}s remaining · breathe comfortably`;if(rem<=0){breathingActive=false;clearInterval(breathingTimer);clearInterval(breathingPhaseTimer);breathingTimer=null;breathingPhaseTimer=null;data.wellnessSessions=data.wellnessSessions||[];data.wellnessSessions.unshift({id:uid(),title:'Completed a 2-minute breathing pause',date:new Date().toISOString(),kind:'breathing'});if(!save())return false;render();toast('Breathing pause complete. Take what helps and leave the rest.','success')}},1000);
 render();toast('Follow the circle gently. Normal, comfortable breathing is enough.');
}
function finishFocusEarly(){if(pendingFocusCompletion){completeTimer();return;}const rem=running?Math.max(0,Math.ceil((endAt-Date.now())/1000)):remaining,seconds=Math.max(0,duration*60-rem);if(seconds<1){toast('Start a session before saving elapsed time.');return;}pendingFocusCompletion={id:focusSessionId||uid(),date:new Date().toISOString(),kind:focusKind,minutes:Math.round(seconds/60*100)/100,seconds,early:true};completeTimer();render();}
function resetTimer(){if(pendingFocusCompletion){toast('Save your finished session before resetting. Use Retry saving session.','error');return}clearInterval(focusTimer);focusTimer=null;running=false;focusSessionId=null;remaining=duration*60;saveTimerState();render()}
function stopTimer(){if(pendingFocusCompletion){toast('Save your finished session before ending it. Use Retry saving session.','error');return}if(running||remaining!==duration*60){if(!confirm('End this session early? It will not be logged as a completed session.'))return}clearInterval(focusTimer);focusTimer=null;running=false;focusSessionId=null;remaining=duration*60;saveTimerState();render();toast('Session ended. You can start again whenever you like.')}
function setDuration(n){if(pendingFocusCompletion){toast('Save your finished session before choosing a new duration.','error');return}if(running){toast('Pause or reset the current session before changing duration.');return}if(!Number.isInteger(Number(n))||Number(n)<1||Number(n)>240){toast('Choose a whole number of minutes between 1 and 240.','error');return;}focusSessionId=null;duration=Number(n);remaining=duration*60;focusKind='Focus';saveTimerState();render()}
