function validateRecordCollections(d){
    if(window.RVTrainingCore)window.RVTrainingCore.validate(d);
 const lists=['clubPlans','questKits','savedLooks','xpEvents','quests','backlog','habits','focusLog','fitnessLogs','foodLogs','waterLogs','workoutPlans','savedRecipes','brainDump','moodLog','reflections','wellnessSessions','playLog','achievements','guestbook','friends'];
 for(const key of lists){
  if(d[key]===undefined)continue;
  if(!Array.isArray(d[key]))throw Error(`${key} must be a list.`);
  const ids=new Set();
  for(const item of d[key]){
   if(!item||typeof item!=='object'||Array.isArray(item))throw Error(`${key} contains an invalid record. Original data was kept.`);
   for(const field of ['title','name','text'])if(item[field]!==undefined&&typeof item[field]!=='string')throw Error(`${key} contains invalid ${field} text.`);
   if(item.id!==undefined){const id=String(item.id);if(ids.has(id))throw Error(`${key} contains duplicate IDs. Repair a copy of the backup first.`);ids.add(id);}
  }
 }
 if(d.profile?.name!==undefined&&typeof d.profile.name!=='string')throw Error('Profile name must be text.');
}
function validateBackup(obj){
 if(!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('The file must contain a JSON object.');
 const d=obj.data||obj;if(!d||typeof d!=='object'||Array.isArray(d))throw Error('No Rowanvale data object was found.');
 // Reject unrelated/empty JSON files: they used to be treated as an empty app backup.
 const known=['profile','settings','quests','backlog','xp','habits','focusLog','moodLog'];
 if(known.filter(k=>Object.hasOwn(d,k)).length<2)throw Error('Not a Rowanvale backup: expected saved profile, settings, or activity lists.');
 for(const k of ['profile','settings','connections','gameCarePlan'])if(d[k]!==undefined&&(!d[k]||typeof d[k]!=='object'||Array.isArray(d[k])))throw Error(`${k} must be an object.`);
 if(d.friends!==undefined&&!Array.isArray(d.friends))throw Error('Friends must be a list.');
 if(d.quests!==undefined&&!Array.isArray(d.quests))throw Error('Quests must be a list.');
 if(d.backlog!==undefined&&!Array.isArray(d.backlog))throw Error('Backlog must be a list.');
 if(d.xp!==undefined&&(!Number.isFinite(d.xp)||d.xp<0))throw Error('XP must be a non-negative number.');
 for(const k of ['clubPlans','questKits','savedLooks','xpEvents','quests','backlog','customShelves','habits','focusLog','fitnessLogs','foodLogs','waterLogs','workoutPlans','savedRecipes','brainDump','moodLog','reflections','wellnessSessions','playLog','achievements'])if(d[k]!==undefined&&!Array.isArray(d[k]))throw Error(`${k} must be a list.`);
 validateRecordCollections(d);
 const out={...clone(DEFAULTS),...d,profile:{...DEFAULTS.profile,...(d.profile||{})},settings:{...DEFAULTS.settings,...(d.settings||{})},connections:{...clone(DEFAULTS.connections),...(d.connections||{})}};for(const platform of Object.keys(DEFAULTS.connections))out.connections[platform]={...DEFAULTS.connections[platform],...((d.connections||{})[platform]||{})};if(!Array.isArray(out.friends))out.friends=[];
 for(const k of ['clubPlans','questKits','savedLooks','xpEvents','quests','backlog','customShelves','habits','focusLog','fitnessLogs','foodLogs','waterLogs','workoutPlans','savedRecipes','brainDump','moodLog','reflections','wellnessSessions','playLog','achievements'])if(!Array.isArray(out[k]))out[k]=clone(DEFAULTS[k]);
 out.gameCarePlan={...DEFAULTS.gameCarePlan,...(d.gameCarePlan||{})};out.xp=Number.isFinite(out.xp)&&out.xp>=0?out.xp:0;out.settings.nutritionGoals={...DEFAULTS.settings.nutritionGoals,...(out.settings.nutritionGoals||{})};out.xpEvents=Array.isArray(out.xpEvents)?out.xpEvents.filter(e=>e&&typeof e.key==='string'&&Number.isFinite(e.amount)):[];out.fanClub=RVFan.sanitize(out.fanClub);if(!d.settings?.online185)out.settings.online185={automaticArtwork:d.living184?.preferences?.online===true,autoSync:false};RVLivingCore.migrate(out);return out;
}
async function importBackup(file){try{if(file.size>12*1024*1024)throw Error('Backup is larger than 12 MB.');const obj=JSON.parse(await file.text());const next=validateBackup(obj);const counts=[['games',next.backlog?.length],['quests',next.quests?.length],['friends',next.friends?.length],['game nights',next.clubPlans?.length]].map(([n,c])=>`${Number(c||0)} ${n}`).join(', ');if(!confirm(`Import Rowanvale backup for ${next.profile?.name||'your profile'}?\n\nFile includes ${counts}.\n\nThis REPLACES your current local workspace. Export your existing backup first if you may need it.`))return;commitReplacement(next);applySettings();render();toast('Backup imported successfully.','success')}catch(e){toast(`Import failed: ${e.message}`,'error')}finally{$('#importFile').value=''}}
function compareVersions(a,b){const aa=String(a).split('.').map(Number),bb=String(b).split('.').map(Number);for(let i=0;i<Math.max(aa.length,bb.length);i++){const x=aa[i]||0,y=bb[i]||0;if(x!==y)return x>y?1:-1}return 0}
async function checkUpdates(){
 updateInfo={...updateInfo,status:'checking',error:null};if(currentView==='updates')render();
 try{
  const response=await fetch(new URL(`./version.json?check=${Date.now()}`,location.href),{cache:'no-store',headers:{'Accept':'application/json'}});
  if(!response.ok)throw Error(`Manifest request returned HTTP ${response.status}.`);
  const remote=await response.json();
  if(typeof remote.version!=='string'||! /^\d+\.\d+\.\d+$/.test(remote.version))throw Error('The hosted manifest has an invalid version field.');
  updateInfo={status:compareVersions(remote.version,APP_VERSION)>0?'available':'current',remote,error:null};
  $('#updateDot').classList.toggle('show',compareVersions(remote.version,APP_VERSION)>0);
  if(currentView==='updates')render();else toast(compareVersions(remote.version,APP_VERSION)>0?`Update available: v${remote.version}`:`Rowanvale is up to date (v${APP_VERSION}).`,compareVersions(remote.version,APP_VERSION)>0?'':'success');
 }catch(e){updateInfo={status:'error',remote:null,error:`${e.message} Check that version.json is deployed beside index.html and the site is online.`};if(currentView==='updates')render();else toast('Could not check for updates. Open Update Center for details.','error')}
}
