 if(id){const q=data.quests.find(x=>x.id===id);if(q)Object.assign(q,fields)}
 else{data.quests.unshift({id:uid(),...fields,completed:false,completedDate:null,xpGranted:false,cycleKey:'',awardedCycles:[],createdAt:new Date().toISOString()})}
 const sourceId=$('#questForm').dataset.brainDumpId;if(!id&&sourceId)data.brainDump=data.brainDump.filter(x=>x.id!==sourceId);
 if(!save()){data=prior;return;}delete $('#questForm').dataset.brainDumpId;$('#questDialog').close();render();toast(id?'Quest updated.':'Quest created. One step at a time.','success');
