$('#friendImportFile')?.addEventListener('change',async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{if(f.size>1024*1024)throw new Error('Roster file is larger than 1 MB.');const raw=JSON.parse(await f.text());if(raw.format!=='vytron-friends-roster'||!Array.isArray(raw.friends))throw new Error('That file is not a Rowanvale roster export.');const seen=new Set((data.friends||[]).map(x=>`${x.name.toLowerCase()}|${x.platform}|${String(x.handle||'').toLowerCase()}`));let added=0;for(const src of raw.friends){if(!src||typeof src.name!=='string'||!src.name.trim())continue;const item={id:uid(),name:src.name.trim().slice(0,60),platform:['PC / Steam','Xbox','PlayStation','Discord','Other'].includes(src.platform)?src.platform:'Other',handle:String(src.handle||'').slice(0,100),game:String(src.game||'').slice(0,100),status:['Available','Busy','Away','Offline'].includes(src.status)?src.status:'Available',profileUrl:safeHttpsUrl(src.profileUrl||''),note:String(src.note||'').slice(0,200)};const key=`${item.name.toLowerCase()}|${item.platform}|${item.handle.toLowerCase()}`;if(!seen.has(key)&&data.friends.length<200){data.friends.push(item);seen.add(key);added++}}if(!save())return false;render();toast(`Roster import complete: ${added} friend card(s) added.`,'success')}catch(err){toast(`Roster import failed: ${err.message}`,'error')}});
function uploadCanvasImage(e,field,maxKB){const file=e.target.files?.[0];e.target.value='';if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/i.test(file.type)||file.size>maxKB*1024){toast(`Choose a PNG/JPG/WebP/GIF under ${maxKB} KB.`, 'error');return}const reader=new FileReader();reader.onload=()=>{const value=String(reader.result||'');if(!safeCanvasImage(value)){toast('Could not read the image.','error');return}const previous=data.settings[field];data.settings[field]=value;if(!save()){data.settings[field]=previous;return}render();toast('Your Orbit artwork is saved locally.','success')};reader.onerror=()=>toast('Image could not be loaded.','error');reader.readAsDataURL(file)}
$('#spaceAvatarFile')?.addEventListener('change',e=>uploadCanvasImage(e,'spaceCustomAvatar',450));
$('#spaceBannerFile')?.addEventListener('change',e=>uploadCanvasImage(e,'spaceCustomBanner',700));
$('#spaceGalleryFile')?.addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(data.settings.spaceGallery.length>=6){toast('The gallery has six pictures already.','error');return}if(!/^image\/(png|jpeg|webp|gif)$/i.test(file.type)||file.size>280*1024){toast('Use a PNG/JPG/WebP/GIF under 280 KB.','error');return}const reader=new FileReader();reader.onload=()=>{const src=String(reader.result||'');if(!safeCanvasImage(src)){toast('Invalid picture.','error');return}const item={id:uid(),image:src,caption:file.name.replace(/\.[^.]+$/,'').slice(0,80)};data.settings.spaceGallery.push(item);if(!save())return;render();toast('Gallery image added.','success')};reader.onerror=()=>toast('Picture could not be loaded.','error');reader.readAsDataURL(file)});
