window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){
 // A successful external save is now the rollback baseline, too. Otherwise a
 // later quota failure can resurrect an older workspace and overwrite this one.
 storageLoadIssue=null;
 data=loadData();committedData=clone(data);
 librarySort=data.settings.librarySort||'recent';libraryView=data.settings.libraryView||'grid';
 applySettings();render();showSaveState(!!storageLoadIssue);
 toast(storageLoadIssue?'Saved data in another tab needs recovery. Open Data & Beta.':'Rowanvale data changed in another tab.',storageLoadIssue?'error':undefined);
}});

function restoreTimer(){try{const tabRaw=sessionStorage.getItem('mindforge.timer'),diskRaw=localStorage.getItem(QUIET_DURABLE_KEY),x=JSON.parse(diskRaw||tabRaw||'null');if(!x)return;const sameTab=!!tabRaw&&JSON.parse(tabRaw)?.owner===x.owner;duration=Number.isInteger(Number(x.duration))&&Number(x.duration)>=1&&Number(x.duration)<=240?Number(x.duration):25;focusKind=x.focusKind==='Break'?'Break':'Focus';endAt=Number.isFinite(Number(x.endAt))?Number(x.endAt):0;focusSessionId=typeof x.focusSessionId==='string'?x.focusSessionId:null;const rem=Number(x.remaining);remaining=x.running===true?Math.max(0,Math.min(duration*60,Math.ceil((endAt-Date.now())/1000))):Number.isFinite(rem)?Math.max(0,Math.min(duration*60,rem)):duration*60;running=x.running===true&&sameTab;if(x.pendingFocusCompletion&&typeof x.pendingFocusCompletion.id==='string'&&Number.isFinite(x.pendingFocusCompletion.minutes)&&x.pendingFocusCompletion.minutes>0&&x.pendingFocusCompletion.minutes<=240){pendingFocusCompletion={...x.pendingFocusCompletion,kind:focusKind};running=false;remaining=0;if(data.focusLog.some(e=>e.id===pendingFocusCompletion.id)){pendingFocusCompletion=null;saveTimerState();}}else if(running&&remaining===0)completeTimer();else if(running){saveTimerState();focusTimer=setInterval(tick,250);}else if(!sameTab&&x.running===true){toast('Your previous focus timer is ready, paused. Resume when you want.');}}catch{}}

function registerPWA(){if('serviceWorker' in navigator && /^https?:$/.test(location.protocol)){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const w=reg.installing;if(w)w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('A new app shell is ready. Open Help & Updates and refresh when convenient.','success')})});reg.update().catch(()=>{})}).catch(e=>console.warn('Service worker registration failed',e)))}}

function initDeviceSignIn(){
 const gate=$('#authGate'),shell=$('#appShell'),form=$('#localSignInForm');
 if(!gate||!shell||!form){console.error('Rowanvale sign-in elements missing');return}
 const landing=$('#authLanding'),wizard=$('#authWizard'),error=$('#authWizardError');
 let onboardStep=0,onboardTheme='rowan';
 function showApp(){rolloverQuests();gate.hidden=true;shell.hidden=false;document.body.classList.add('signed-in');syncSkipLink(true);applySettings();render();setTimeout(checkIncomingFriendCard,0)}
 function showGate(){deviceProfile=null;RVConnect.pause();RVReset.pause();RVCovers.pause();shell.hidden=true;gate.hidden=false;landing.hidden=false;wizard.hidden=true;document.body.classList.remove('signed-in');syncSkipLink(false);document.title=`Welcome · Rowanvale ${APP_VERSION}`}
 function showWizard(){landing.hidden=true;wizard.hidden=false;onboardStep=0;onboardTheme='rowan';$('#onboardName').value='';$('#onboardTagline').value='';$('#onboardAvatar').value='✦';$('#onboardReduceMotion').checked=false;$$('[data-onboard-theme]').forEach(btn=>{const active=btn.dataset.onboardTheme==='rowan';btn.classList.toggle('selected',active);btn.setAttribute('aria-checked',String(active))});$$('.auth-interest-grid input').forEach(input=>input.checked=input.value==='Gaming');renderWizard();$('#onboardName').focus()}
 function renderWizard(){
  $$('.auth-wizard-step').forEach((step,i)=>step.hidden=i!==onboardStep);
  $$('.auth-step-tracks span').forEach((part,i)=>part.classList.toggle('active',i<=onboardStep));
  $('#authStepLabel').textContent=`STEP ${onboardStep+1} OF 3`;
  $('#authWizardTitle').textContent=['Start with your name.','Find your atmosphere.','Make it yours.'][onboardStep];
  $('#authStepDescription').textContent=['A name, a symbol, and a little personality.','Your app, your colors, your pace.','Bring your interests along for the ride.'][onboardStep];
  $('#authWizardPrev').hidden=onboardStep===0;$('#authWizardNext').hidden=onboardStep===2;$('#authWizardFinish').hidden=onboardStep!==2;
  error.hidden=true;error.textContent='';
 }
 function showWizardError(message){error.textContent=message;error.hidden=false}
 function createProfile(name,email='',options={}){
  const normalized=name.trim().slice(0,40);
  if(!normalized)return false;
  const newProfile={name:normalized,email,guest:!!options.guest,createdAt:new Date().toISOString()};
  try{localStorage.setItem(PROFILE_KEY,JSON.stringify(newProfile))}
  catch{toast('Browser storage is blocked. Enable site storage to continue.','error');return false}
  deviceProfile=newProfile;
  data=loadData();data.profile.name=normalized;
  if(typeof options.tagline==='string'&&options.tagline.trim())data.profile.tagline=options.tagline.trim().slice(0,100);
  if(options.avatar)data.profile.avatarEmoji=options.avatar;
  if(options.theme){data.settings.theme=options.theme;data.settings.accent=({rowan:'#e6a26b',afterglow:'#63e9cd',redline:'#ff5364',indigo:'#b6a2ff',moss:'#b9f27c'})[options.theme]||'#63e9cd'}
  if(typeof options.reducedMotion==='boolean')data.settings.reducedMotion=options.reducedMotion;
  if(Array.isArray(options.interests))data.profile.interests=options.interests.join(' · ');
  if(!save()){
   try{localStorage.removeItem(PROFILE_KEY)}catch{}
   deviceProfile=null;return false;
  }
  currentView='myday';showApp();toast(options.guest?'Guest space ready. You can personalize it any time.':`Welcome to Rowanvale, ${normalized}.`,'success');return true;
 }
 $('#authGetStarted')?.addEventListener('click',showWizard);
 $('#authWizardExit')?.addEventListener('click',()=>{wizard.hidden=true;landing.hidden=false;$('#authGetStarted').focus()});
 const guest=()=>createProfile('Guest Explorer','',{guest:true});
 $('#authSkipIntro')?.addEventListener('click',guest);
 $('#authWizardSkip')?.addEventListener('click',guest);
 $('#onboardName')?.addEventListener('input',e=>{$('#authPreviewName').textContent=e.target.value.trim()||'Your Orbit'});
 $('#onboardTagline')?.addEventListener('input',e=>{$('#authPreviewTagline').textContent=e.target.value.trim()||'Your corner of the universe'});
 $('#onboardAvatar')?.addEventListener('change',e=>{$('#authPreviewAvatar').textContent=e.target.value});
 $$('[data-onboard-theme]').forEach(button=>button.addEventListener('click',()=>{onboardTheme=button.dataset.onboardTheme;$$('[data-onboard-theme]').forEach(b=>{const active=b===button;b.classList.toggle('selected',active);b.setAttribute('aria-checked',String(active))})}));
 $('#authWizardPrev')?.addEventListener('click',()=>{onboardStep=Math.max(0,onboardStep-1);renderWizard()});
 const wizardNameValid=()=>{const name=$('#onboardName').value.trim();if(!name){showWizardError('Give your space a display name to continue.');$('#onboardName').focus();return false}return true};
 $('#authWizardNext')?.addEventListener('click',()=>{if(onboardStep===0&&!wizardNameValid())return;onboardStep=Math.min(onboardStep+1,2);renderWizard()});
 $('#authWizardForm')?.addEventListener('submit',e=>{
  e.preventDefault();if(!wizardNameValid())return;
  if(onboardStep!==2){onboardStep=Math.min(onboardStep+1,2);renderWizard();return}
  const interests=$$('.auth-interest-grid input:checked').map(x=>x.value);
  createProfile($('#onboardName').value,'',{tagline:$('#onboardTagline').value,avatar:$('#onboardAvatar').value,theme:onboardTheme,reducedMotion:$('#onboardReduceMotion').checked,interests});
 });
 const savedProfile=()=>{try{const saved=JSON.parse(localStorage.getItem(PROFILE_KEY)||'null');if(saved&&typeof saved.name==='string'&&saved.name.trim()&&(typeof saved.email==='string'||saved.guest===true))return saved}catch{}return null};
 const existingName=()=>{try{const raw=localStorage.getItem(STORAGE_KEY)||localStorage.getItem(LEGACY_KEY);if(!raw)return '';const previous=JSON.parse(raw);const n=previous?.profile?.name;if(typeof n!=='string'||!n.trim()||n.trim()==='Guest Explorer'||n.trim()==='Player')return '';return n.trim().slice(0,40)}catch{return ''}};
 function updateReturnCard(){const name=existingName(),card=$('#authReturnCard');if(card){card.hidden=!name;if(name)$('#authReturnName').textContent=name}}
 $('#authContinueSaved')?.addEventListener('click',()=>{const name=existingName();if(!name)return;createProfile(name,'',{resume:true})});
 const saved=savedProfile();
 if(saved){deviceProfile=saved;data=loadData();committedData=clone(data);showApp()}else{showGate();updateReturnCard()}

 // Keep the original device-profile entry point compatible with versions 9–11.1.
 window.vytronHandleDeviceSignIn=function(event){
  if(event)event.preventDefault();const name=$('#signInName').value.trim(),emailInput=$('#signInEmail'),email=emailInput.value.trim();
  if(!name||(email&&!emailInput.checkValidity())){form.reportValidity();return false}
  createProfile(name,email);return false;
 };
 $('#signOutTop')?.addEventListener('click',()=>{try{localStorage.removeItem(PROFILE_KEY)}catch{}showGate();updateReturnCard();$('#signInName').value='';$('#signInEmail').value='';toast('Signed out. Local app data was kept.','success')});
}

